SELECT
FROM spots s
INNER JOIN sub_categories sc ON sc.id = s.sub_category_id INNER JOIN categories c ON c.id = sc.category_id WHERE s.deleted_at IS NULL ORDER BY s.created_at DESC LIMIT #{limit}

SELECT
FROM spots s
INNER JOIN sub_categories sc ON sc.id = s.sub_category_id INNER JOIN categories c ON c.id = sc.category_id WHERE s.deleted_at IS NULL ORDER BY s.updated_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE spots
SET deleted_at = CURRENT_TIMESTAMP
WHERE id = #{spotId}
